alter table HUNTTECH_INTERNAL_EMAILER add constraint FK_HUNTTECH_INTERNAL_EMAILER_ON_FROM_EMAIL foreign key (FROM_EMAIL_ID) references SEC_USER(ID);
alter table HUNTTECH_INTERNAL_EMAILER add constraint FK_HUNTTECH_INTERNAL_EMAILER_ON_TO_EMAIL foreign key (TO_EMAIL_ID) references HUNTTECH_JOB_CANDIDATE(ID);
alter table HUNTTECH_INTERNAL_EMAILER add constraint FK_HUNTTECH_INTERNAL_EMAILER_ON_EMAIL_TEMPLATE foreign key (EMAIL_TEMPLATE_ID) references HUNTTECH_INTERNAL_EMAIL_TEMPLATE(ID);
create index IDX_HUNTTECH_INTERNAL_EMAILER_ON_FROM_EMAIL on HUNTTECH_INTERNAL_EMAILER (FROM_EMAIL_ID);
create index IDX_HUNTTECH_INTERNAL_EMAILER_ON_TO_EMAIL on HUNTTECH_INTERNAL_EMAILER (TO_EMAIL_ID);
create index IDX_HUNTTECH_INTERNAL_EMAILER_ON_EMAIL_TEMPLATE on HUNTTECH_INTERNAL_EMAILER (EMAIL_TEMPLATE_ID);
